class Solution {
public:
    long long makeSubKSumEqual(vector<int>& arr, int k) {
        int n = (int)arr.size();
        int g = gcd(n, k);
        long long ans = 0;
        for (int i = 0; i < g; i++) {
            vector<int> group;
            for (int j = i; j < n; j += g) group.push_back(arr[j]);
            int m = (int)group.size();
            nth_element(group.begin(), group.begin() + m / 2, group.end());
            int med = group[m / 2];
            for (int x : group) ans += (long long)abs(x - med);
        }
        return ans;
    }
private:
    int gcd(int a, int b) {
        while (b) { int t = a % b; a = b; b = t; }
        return a;
    }
};
